import{_ as a,o as t,c as i,al as o}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"System Failure Injection","description":"","frontmatter":{},"headers":[],"relativePath":"en/debug/failure_injection.md","filePath":"en/debug/failure_injection.md"}'),s={name:"en/debug/failure_injection.md"};function d(n,e,r,l,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="system-failure-injection" tabindex="-1">System Failure Injection <a class="header-anchor" href="#system-failure-injection" aria-label="Permalink to &quot;System Failure Injection&quot;">​</a></h1><p>System failure injection allows you to induce different types of sensor and system failures, either via MAVLink (using <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_INJECT_FAILURE" target="_blank" rel="noreferrer">MAV_CMD_INJECT_FAILURE</a> or via the <a href="https://mavsdk.mavlink.io/main/en/cpp/api_reference/classmavsdk_1_1_failure.html" target="_blank" rel="noreferrer">MAVSDK failure plugin</a>), or &quot;manually&quot; via a PX4 console like the <a href="./../debug/mavlink_shell#mavlink-shell">MAVLink shell</a>. This enables easier testing of <a href="./../config/safety">safety failsafe</a> behaviour, and more generally, of how PX4 behaves when systems and sensors stop working correctly.</p><p>Failure injection is disabled by default, and can be enabled using the <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a> parameter.</p><p>Failures can be injected both in simulation and on real hardware; this requires firmware built with the failure-injection module. The command always goes through the same firmware failure-injection module — whether it arrives over MAVLink or from the console, the accepted combinations are identical. What differs is whether a <em>consumer</em> applies the failure, and that depends on the environment.</p><h2 id="supported-failure-types" tabindex="-1">Supported Failure Types <a class="header-anchor" href="#supported-failure-types" aria-label="Permalink to &quot;Supported Failure Types&quot;">​</a></h2><p>The table lists the failure types that actually take effect per environment: <code>off</code>, <code>stuck</code>, <code>wrong</code> (<code>ok</code> is not listed, but clears an active injection on all environments). A <code>—</code> means the module still accepts the command, but no consumer applies it in that environment.</p><table tabindex="0"><thead><tr><th>Component</th><th><a href="./../sim_gazebo_gz/">Gazebo</a> (gz)</th><th><a href="./../sim_sih/">SIH</a></th><th><code>simulator_mavlink</code> (Gazebo Classic/JMAVSim)</th><th>Hardware</th></tr></thead><tbody><tr><td><code>gyro</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td></tr><tr><td><code>accel</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td></tr><tr><td><code>mag</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td></tr><tr><td><code>baro</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td></tr><tr><td><code>distance_sensor</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td><td><code>off</code>, <code>stuck</code></td></tr><tr><td><code>gps</code></td><td><code>off</code>, <code>stuck</code>, <code>wrong</code></td><td><code>off</code>, <code>stuck</code>, <code>wrong</code></td><td><code>off</code>, <code>stuck</code>, <code>wrong</code></td><td><code>off</code>, <code>stuck</code>, <code>wrong</code></td></tr><tr><td><code>airspeed</code></td><td><code>off</code>, <code>stuck</code>, <code>wrong</code></td><td>—</td><td><code>off</code>, <code>wrong</code></td><td>—</td></tr><tr><td><code>vio</code></td><td>—</td><td>—</td><td><code>off</code></td><td>—</td></tr><tr><td><code>battery</code></td><td><code>off</code>, <code>wrong</code></td><td><code>off</code>, <code>wrong</code></td><td><code>off</code>, <code>wrong</code></td><td><code>off</code>, <code>wrong</code></td></tr><tr><td><code>traffic</code></td><td><code>off</code></td><td><code>off</code></td><td><code>off</code></td><td><code>off</code></td></tr><tr><td><code>motor</code></td><td><code>off</code></td><td><code>off</code></td><td><code>off</code></td><td><code>off</code></td></tr><tr><td><code>esc</code></td><td><code>off</code>, <code>wrong</code></td><td><code>off</code>, <code>wrong</code></td><td><code>off</code>, <code>wrong</code></td><td><code>off</code>, <code>wrong</code></td></tr><tr><td><code>can</code></td><td>—</td><td>—</td><td>—</td><td><code>off</code></td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><code>gps off | stuck | wrong</code> on Gazebo (Gz): applied to the GNSS data from the simulator&#39;s own sensor as well as to the simulated-GPS module (<a href="./../advanced_config/parameter_reference#SIM_GZ_EN_GPS">SIM_GZ_EN_GPS</a> <code>0</code>).</li><li><code>airspeed off | stuck | wrong</code> on Gazebo (Gz): only injectable when airspeed is provided by the simulated-airspeed module (<a href="./../advanced_config/parameter_reference#SENS_EN_ARSPDSIM">SENS_EN_ARSPDSIM</a>); worlds that model an airspeed sensor directly are not injected.</li><li><code>battery wrong</code> reports the remaining charge just below the <a href="./../advanced_config/parameter_reference#SYS_FAIL_BAT_LVL">SYS_FAIL_BAT_LVL</a> warning threshold to trigger the battery failsafe; <code>off</code> stops publishing the battery status entirely.</li><li><code>traffic off</code> suppresses incoming reports and marks the ADS-B/FLARM link unhealthy.</li><li><code>motor off</code> also requires <a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a>.</li><li><code>esc off</code> reports the addressed ESC as offline and blanks its telemetry; <code>esc wrong</code> keeps it online but reports implausible telemetry (voltage and current at 10% of the real value, RPM 10x). ESCs are addressed by motor instance (the ESC&#39;s actuator function), so <code>-i 1</code> targets the ESC driving motor 1.</li><li>On hardware, ESC injection is applied only by the UAVCAN (DroneCAN) ESC driver; the other ESC drivers (DShot, Cyphal, VOXL, TAP ESC) publish their telemetry unmodified.</li><li><code>can off</code> takes the addressed CAN bus offline entirely, so every node on it stops responding; the instance selects the bus. Only applied on fmu-v6x-class hardware.</li></ul></div><p>Sensors delivered through the shared driver layer (IMU, magnetometer, barometer, rangefinder via the <code>PX4*</code> sensor wrappers) support <code>off</code>/<code>stuck</code> in every environment that uses that layer — including the Gazebo and SIH sensor simulators, which feed synthesized measurements through the same wrappers. The remaining gaps are backend-specific: GPS and airspeed are handled by dedicated simulator code (see the GPS and airspeed notes in the info box above), SIH does not simulate an injectable airspeed. Components not listed (<code>optical_flow</code>, <code>servo</code>, <code>avoidance</code>, <code>rc_signal</code>, <code>mavlink_signal</code>) are rejected everywhere (<code>MAV_RESULT_UNSUPPORTED</code>); see the note below on NACK behaviour.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 may accept a command to set a particular failure mode even it that mode is not supported by your simulator.</p><p>All <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_INJECT_FAILURE" target="_blank" rel="noreferrer">MAV_CMD_INJECT_FAILURE</a> commands are handled internally by the failure-injection module, which acknowledges each command and republishes the active failures for the sensor/actuator simulators to apply. The failure-injection module will NACK the command with <a href="https://mavlink.io/en/messages/common.html#MAV_RESULT_UNSUPPORTED" target="_blank" rel="noreferrer">MAV_RESULT_UNSUPPORTED</a> for failure combinations that are not implemented by PX4 or any simulator. However it the module will accept (respond with <a href="https://mavlink.io/en/messages/common.html#MAV_MISSION_ACCEPTED" target="_blank" rel="noreferrer">MAV_MISSION_ACCEPTED</a>) for any other failure-type, even if it is not supported by your <em>particular</em> simulator.</p></div><h2 id="failure-system-command" tabindex="-1">Failure System Command <a class="header-anchor" href="#failure-system-command" aria-label="Permalink to &quot;Failure System Command&quot;">​</a></h2><p>Failures can be injected using the <a href="./../modules/modules_command#failure">failure system command</a> from any PX4 <a href="./../debug/consoles">console/shell</a> (such as the <a href="./../debug/mavlink_shell#qgroundcontrol-mavlink-console">QGC MAVLink Console</a> or SITL <em>pxh shell</em>), specifying both the target and type of the failure.</p><h3 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h3><p>The full syntax of the <a href="./../modules/modules_command#failure">failure</a> command is:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">componen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">failure_typ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">instance_numbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">instance_bitmas</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><p>where:</p><ul><li><em>component</em>: <ul><li>Sensors: <ul><li><code>gyro</code>: Gyroscope</li><li><code>accel</code>: Accelerometer</li><li><code>mag</code>: Magnetometer</li><li><code>baro</code>: Barometer</li><li><code>gps</code>: Global navigation satellite system</li><li><code>optical_flow</code>: Optical flow.</li><li><code>vio</code>: Visual inertial odometry</li><li><code>distance_sensor</code>: Distance sensor (rangefinder).</li><li><code>airspeed</code>: Airspeed sensor</li></ul></li><li>Systems: <ul><li><code>battery</code>: Battery</li><li><code>motor</code>: Motor</li><li><code>esc</code>: ESC telemetry</li><li><code>servo</code>: Servo</li><li><code>avoidance</code>: Obstacle/collision avoidance system</li><li><code>traffic</code>: Traffic avoidance (ADS-B/transponder)</li><li><code>rc_signal</code>: RC Signal</li><li><code>mavlink_signal</code>: MAVLink data telemetry connection</li><li><code>can</code>: CAN bus. The instance selects the bus. Supported on fmu-v6x-class hardware.</li></ul></li></ul></li><li><em>failure_type</em>: <ul><li><code>ok</code>: Publish as normal (Disable failure injection)</li><li><code>off</code>: Stop publishing</li><li><code>stuck</code>: Constantly report the same value which <em>can</em> happen on a malfunctioning sensor</li><li><code>garbage</code>: Publish random noise. This looks like reading uninitialized memory</li><li><code>wrong</code>: Publish invalid values that still look reasonable/aren&#39;t &quot;garbage&quot;</li><li><code>slow</code>: Publish at a reduced rate</li><li><code>delayed</code>: Publish valid data with a significant delay</li><li><code>intermittent</code>: Publish intermittently</li></ul></li><li><em>instance number</em> (optional): Instance number of affected sensor. 0 (default) indicates all sensors of specified type.</li><li><em>instance bitmask</em> (optional): address several instances at once (bit 0 = first instance, bit 1 = second, …; decimal or <code>0x</code> hex). Used only when <code>-i</code> is omitted. Example: <code>-m 0x5</code> targets instances 1 and 3.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>GPS implements only the <code>off</code>, <code>stuck</code>, and <code>wrong</code> failure modes; the other failure types have no effect on it. <code>gps wrong</code> makes the addressed receiver report the fix type selected by <a href="./../advanced_config/parameter_reference#SYS_FAIL_GPS_WRG">SYS_FAIL_GPS_WRG</a> and the jamming state selected by <a href="./../advanced_config/parameter_reference#SYS_FAIL_GPS_JAM">SYS_FAIL_GPS_JAM</a> (<code>Unchanged</code> keeps the receiver&#39;s own state), and leaves the reported position untouched.</p></div><h2 id="rc-switch-trigger" tabindex="-1">RC Switch Trigger <a class="header-anchor" href="#rc-switch-trigger" aria-label="Permalink to &quot;RC Switch Trigger&quot;">​</a></h2><p>A failure can also be injected from an RC switch, without a console or telemetry link. This is useful for in-flight hardware testing. It is configured with the following parameters:</p><ul><li><a href="./../advanced_config/parameter_reference#SYS_FAIL_RC_SRC">SYS_FAIL_RC_SRC</a>: the auxiliary RC input that triggers the failure — <code>0</code> disables it, <code>1</code>–<code>6</code> select AUX1–AUX6 (mapped via <code>RC_MAP_AUXn</code>).</li><li><a href="./../advanced_config/parameter_reference#SYS_FAIL_RC_UNIT">SYS_FAIL_RC_UNIT</a>: the affected component (the <code>FAILURE_UNIT</code> value; e.g. <code>101</code> = motor).</li><li><a href="./../advanced_config/parameter_reference#SYS_FAIL_RC_MODE">SYS_FAIL_RC_MODE</a>: the failure type (the <code>FAILURE_TYPE</code> value; e.g. <code>1</code> = off).</li><li><a href="./../advanced_config/parameter_reference#SYS_FAIL_RC_INST">SYS_FAIL_RC_INST</a>: the affected instances, as a bitmask (bit 0 = instance 1, e.g. <code>5</code> = instances 1 and 3; <code>0</code> = all instances).</li></ul><p>While the selected aux switch is on the configured failure is injected; switching it back off clears the failure. The injection goes through the same path as the console/MAVLink commands, so for a motor it stops the motor exactly as <code>failure motor off</code> does (which also requires <a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a>).</p><h2 id="mavsdk-failure-plugin" tabindex="-1">MAVSDK Failure Plugin <a class="header-anchor" href="#mavsdk-failure-plugin" aria-label="Permalink to &quot;MAVSDK Failure Plugin&quot;">​</a></h2><p>The <a href="https://mavsdk.mavlink.io/main/en/cpp/api_reference/classmavsdk_1_1_failure.html" target="_blank" rel="noreferrer">MAVSDK failure plugin</a> can be used to programmatically inject failures. It is used in <a href="./../test_and_ci/integration_testing_mavsdk">PX4 Integration Testing</a> to simulate failure cases (for example, see <a href="https://github.com/PX4/PX4-Autopilot/blob/main/test/mavsdk_tests/autopilot_tester.cpp" target="_blank" rel="noreferrer">PX4-Autopilot/test/mavsdk_tests/autopilot_tester.cpp</a>).</p><p>The plugin API is a direct mapping of the failure command shown above, with a few additional error signals related to the connection.</p><h2 id="example-gps" tabindex="-1">Example: GPS <a class="header-anchor" href="#example-gps" aria-label="Permalink to &quot;Example: GPS&quot;">​</a></h2><p>To test the GPS failsafe by stopping GPS:</p><ol><li><p>Enable the <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a> parameter.</p></li><li><p>Enter the following commands on the MAVLink console or SITL <em>pxh shell</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop GPS publishing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restart GPS publishing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ok</span></span></code></pre></div></li></ol><h2 id="example-motor" tabindex="-1">Example: Motor <a class="header-anchor" href="#example-motor" aria-label="Permalink to &quot;Example: Motor&quot;">​</a></h2><p>To stop a motor mid-flight without the system anticipating it or excluding it from allocation effectiveness:</p><ol><li><p>Enable the <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a> parameter.</p></li><li><p>Enable <a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a> parameter to allow turning off motors.</p></li><li><p>Enter the following commands on the MAVLink console or SITL <em>pxh shell</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Turn off first motor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> motor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Turn it back on</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> motor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ok</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div></li></ol><h2 id="example-battery" tabindex="-1">Example: Battery <a class="header-anchor" href="#example-battery" aria-label="Permalink to &quot;Example: Battery&quot;">​</a></h2><p>To trigger the battery failsafe by reporting a depleted pack:</p><ol><li><p>Enable the <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a> parameter.</p></li><li><p>Optionally select the injected warning level with <a href="./../advanced_config/parameter_reference#SYS_FAIL_BAT_LVL">SYS_FAIL_BAT_LVL</a>: Warn, Critical or Emergency. The reported remaining charge is set just below the matching threshold (<a href="./../advanced_config/parameter_reference#BAT_LOW_THR">BAT_LOW_THR</a>, <a href="./../advanced_config/parameter_reference#BAT_CRIT_THR">BAT_CRIT_THR</a> or <a href="./../advanced_config/parameter_reference#BAT_EMERGEN_THR">BAT_EMERGEN_THR</a>).</p></li><li><p>Enter the following commands on the MAVLink console or SITL <em>pxh shell</em>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Report the battery as depleted at the SYS_FAIL_BAT_LVL warning level -&gt; battery failsafe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> battery</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrong</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop publishing the battery status entirely</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> battery</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Stop injecting the failure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> battery</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ok</span></span></code></pre></div></li></ol>`,34)])])}const m=a(s,[["render",d]]);export{f as __pageData,m as default};
